#include <upc.h>
#include <stdio.h>
shared [1] int x[4];
int main(){
  upc_forall(int i=0; i<THREADS; i++; i%THREADS){
    printf("hello block %d thr %d\n", i, MYTHREAD);
  }
  upc_barrier;
  upc_forall(int i=0;i<4;i++;i){ x[i] = i*10; upc_barrier; if(MYTHREAD==0) printf("x[%d]=%d\n", i, *x[i]); }
  upc_barrier;
  shared int *p = upc_all_alloc(4, sizeof(int)*4);
  shared int *base = p;
  upc_forall(int i=0;i<THREADS;i++;i){
    shared int *loc = (shared int*)((void*)(base + (i*4)));
    for(int j=0;j<4;j++) *loc = i*100+j, loc++;
    upc_barrier;
    if(MYTHREAD==0){ shared int *q=base; for(int j=0;j<16;j++){ printf("%d ", *q); q++; } printf("\n"); }
    upc_barrier;
  }
  upc_all_free(base);
  return 0;
}
EOF
