#include <upc.h>
#include <stdio.h>
typedef struct { uint64_t k; int a; } Rec;
shared Rec *arr;
shared int cnt;
int main(){
  arr = (shared Rec*)upc_all_alloc(4*THREADS, sizeof(Rec));
  upc_barrier;
  { shared Rec *p = arr + MYTHREAD; p->k = MYTHREAD*5; p->a = MYTHREAD; }
  upc_barrier;
  { int t=0; shared Rec *p = arr; for(;p<(arr+4*THREADS);p++){ int v=p->a; uint64_t k=p->k; if(v) printf("t%d k=%llu a=%d\n",MYTHREAD,(unsigned long long)k,v); } }
  upc_barrier;
  *cnt = 5; upc_barrier; { int v=*cnt; if(MYTHREAD==0) printf("cnt=%d\n", v); }
